class Base:
    def greet(self):
        return 'hi'

class Child(Base):
    pass

c = Child()
print(c.greet())

class Box:
    def __init__(self, size):
        self.size = size
    def __eq__(self, other):
        return self.size == other.size

print(Box(5) == Box(5))

class Animal:
    def speak(self):
        return '...'

class Dog(Animal):
    def speak(self):
        return 'Woof'

d = Dog()
print(d.speak())

class Cat:
    def speak(self):
        return 'Meow'

class Cow:
    def speak(self):
        return 'Moo'

def announce(animal):
    return animal.speak()

print(announce(Cow()))

class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __str__(self):
        return f'Point({self.x}, {self.y})'

p = Point(1, 2)
print(str(p))
